   587  static int
   588  parse_odf(const unsigned char * buf, size_t buflen, struct sc_pkcs15_card *p15card)
   589  {
   590          const unsigned char *p = buf;
   591          size_t left = buflen;
   592          int r, i, type;
   593          struct sc_path path;
   594          struct sc_asn1_entry asn1_obj_or_path[] = {
   595                  { "path", SC_ASN1_PATH, SC_ASN1_CONS | SC_ASN1_SEQUENCE, 0, &path, NULL },
   596                  { NULL, 0, 0, 0, NULL, NULL }
   597          };
   598          struct sc_asn1_entry asn1_odf[10];
   599
   600          sc_copy_asn1_entry(c_asn1_odf, asn1_odf);
   601          for (i = 0; asn1_odf[i].name != NULL; i++)
   602                  sc_format_asn1_entry(asn1_odf + i, asn1_obj_or_path, NULL, 0);
   603          while (left > 0) {
   604                  r = sc_asn1_decode_choice(p15card->card->ctx, asn1_odf, p, left, &p, &left);
   605                  if (r == SC_ERROR_ASN1_END_OF_CONTENTS)
   606                          break;
   607                  if (r < 0)
   608                          return r;
   609                  type = r;
   610                  if (p15card->file_app) {
   611                          r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &path);
   612                          if (r < 0)
   613                                  return r;
   614                          r = sc_pkcs15_add_df(p15card, odf_indexes[type], &path);
   615                          if (r)
   616                                  return r;
   617                  }
   618          }
   619          return 0;
   620  }
